package dev.studyforge.banking.domain; import java.math.*; import java.util.*; public record Money(BigDecimal amount,Currency currency) implements Comparable<Money>{public Money{Objects.requireNonNull(amount);Objects.requireNonNull(currency);if(amount.scale()>currency.getDefaultFractionDigits())throw new InvalidBankingOperationException("Too many fraction digits for "+currency);amount=amount.setScale(currency.getDefaultFractionDigits(),RoundingMode.UNNECESSARY);}public static Money of(String a,String c){return new Money(new BigDecimal(a),Currency.getInstance(c));}public static Money zero(Currency c){return new Money(BigDecimal.ZERO,c);}public boolean isPositive(){return amount.signum()>0;}public Money add(Money o){same(o);return new Money(amount.add(o.amount),currency);}public Money subtract(Money o){same(o);return new Money(amount.subtract(o.amount),currency);}private void same(Money o){Objects.requireNonNull(o);if(!currency.equals(o.currency))throw new CurrencyMismatchException(currency,o.currency);}public int compareTo(Money o){same(o);return amount.compareTo(o.amount);}}
